1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"math/big"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14		"unicode/utf16"
15		"unicode/utf8"
16	)
17	
18	// Point 是一条序列上某个时间戳的采样值。
19	type Point struct {
20		Timestamp int64   `json:"timestamp"`
21		Value     float64 `json:"value"`
22	}
23	
24	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
25	type SeriesView struct {
26		Name   string            `json:"name"`
27		Labels map[string]string `json:"labels"`
28		Points []Point           `json:"points"`
29	}
30	
31	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
32	type QuerySeries struct {
33		Name    string            `json:"name"`
34		Labels  map[string]string `json:"labels"`
35		Count   int               `json:"count"`
36		Average float64           `json:"average"`
37	}
38	
39	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
40	type QueryResult struct {
41		Status string        `json:"status"`
42		Op     string        `json:"op"`
43		Series []QuerySeries `json:"series"`
44	}
45	
46	// BatchResult 是一批采样点写入成功后的结果。
47	type BatchResult struct {
48		Status     string       `json:"status"`
49		Added      int          `json:"added"`
50		Duplicates int          `json:"duplicates"`
51		Series     []SeriesView `json:"series"`
52	}
53	
54	// SeriesRef 标识一条序列：指标名加完整标签集合。
55	// 缺少某个标签与该标签值为空字符串属于不同序列。
56	type SeriesRef struct {
57		Name   string            `json:"name"`
58		Labels map[string]string `json:"labels"`
59	}
60	
61	// Conflict 描述同一序列同一时间戳已存在不同的值。
62	type Conflict struct {
63		Series    SeriesRef `json:"series"`
64		Timestamp int64     `json:"timestamp"`
65		Existing  float64   `json:"existing"`
66		Submitted float64   `json:"submitted"`
67	}
68	
69	// LineError 是一行（一批）输入失败后的结构化结果。
70	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
71	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
72	type LineError struct {
73		Status   string    `json:"status"`
74		Line     int       `json:"line,omitempty"`
75		Index    int       `json:"index,omitempty"`
76		Error    string    `json:"error"`
77		Conflict *Conflict `json:"conflict,omitempty"`
78	}
79	
80	// MetricStore 保存一次命令运行期间已写入的指标数据，仅存在于内存中，进程结束即丢弃。
81	type MetricStore struct {
82		series map[seriesID]*storedSeries
83	}
84	
85	// seriesID 是序列的规范身份，标签书写顺序不影响身份。
86	type seriesID struct {
87		name string
88		// sig 为排序后标签键值对的长度前缀拼接，避免不同写法产生碰撞。
89		sig string
90	}
91	
92	type storedSeries struct {
93		ref    SeriesRef
94		points map[int64]float64
95	}
96	
97	// NewMetricStore 创建一个空的指标存储。
98	func NewMetricStore() *MetricStore {
99		return &MetricStore{series: make(map[seriesID]*storedSeries)}
100	}
101	
102	// cloneLabels 返回标签集合的独立副本；空标签仍复制为非 nil 的空集合，
103	// 调用方对副本的增删改不影响存储中的序列身份。
104	func cloneLabels(labels map[string]string) map[string]string {
105		out := make(map[string]string, len(labels))
106		for k, v := range labels {
107			out[k] = v
108		}
109		return out
110	}
111	
112	func sortedKeys(m map[string]string) []string {
113		keys := make([]string, 0, len(m))
114		for k := range m {
115			keys = append(keys, k)
116		}
117		sort.Strings(keys)
118		return keys
119	}
120	
121	func makeSeriesID(name string, labels map[string]string) seriesID {
122		var b strings.Builder
123		for _, k := range sortedKeys(labels) {
124			v := labels[k]
125			fmt.Fprintf(&b, "%d:%s;%d:%s;", len(k), k, len(v), v)
126		}
127		return seriesID{name: name, sig: b.String()}
128	}
129	
130	// labelPair 是标签键值对字典序比较的单元。
131	type labelPair struct {
132		Key, Value string
133	}
134	
135	func sortedPairs(labels map[string]string) []labelPair {
136		keys := sortedKeys(labels)
137		pairs := make([]labelPair, len(keys))
138		for i, k := range keys {
139			pairs[i] = labelPair{Key: k, Value: labels[k]}
140		}
141		return pairs
142	}
143	
144	func compareLabelPairs(a, b []labelPair) int {
145		n := len(a)
146		if len(b) < n {
147			n = len(b)
148		}
149		for i := 0; i < n; i++ {
150			if a[i].Key != b[i].Key {
151				return strings.Compare(a[i].Key, b[i].Key)
152			}
153			if a[i].Value != b[i].Value {
154				return strings.Compare(a[i].Value, b[i].Value)
155			}
156		}
157		switch {
158		case len(a) < len(b):
159			return -1
160		case len(a) > len(b):
161			return 1
162		}
163		return 0
164	}
165	
166	var (
167		jsonIntegerRE = regexp.MustCompile(`^-?(0|[1-9][0-9]*)$`)
168		jsonNumberRE  = regexp.MustCompile(`^-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?$`)
169	)
170	
171	// ProcessLine 处理一行非空输入：JSON 数组为写入批次，JSON 对象为查询/操作。
172	// 成功时返回 BatchResult 或 *QueryResult；失败返回 *LineError（Index 始终为零）。
173	func (s *MetricStore) ProcessLine(line string) (any, *LineError) {
174		top, ok, lerr := decodeTopValue(line)
175		if lerr != nil {
176			return nil, lerr
177		}
178		switch ok {
179		case '[':
180			var items []json.RawMessage
181			if err := json.Unmarshal(top, &items); err != nil {
182				return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
183			}
184			return s.ingestItems(items)
185		case '{':
186			return s.queryFromObject(top)
187		default:
188			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
189		}
190	}
191	
192	// IngestLine 解析并写入一行（一批）采样点。成功返回 BatchResult；
193	// 失败返回 *LineError，此时此前各批数据保留、本批不写入任何数据。
194	func (s *MetricStore) IngestLine(line string) (*BatchResult, *LineError) {
195		top, ok, lerr := decodeTopValue(line)
196		if lerr != nil {
197			return nil, lerr
198		}
199		if ok != '[' {
200			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples"}
201		}
202		var items []json.RawMessage
203		if err := json.Unmarshal(top, &items); err != nil {
204			return nil, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
205		}
206		return s.ingestItems(items)
207	}
208	
209	// QueryLine 解析并执行一行查询对象。成功返回 QueryResult；查询只读，不改变存储。
210	func (s *MetricStore) QueryLine(line string) (*QueryResult, *LineError) {
211		top, ok, lerr := decodeTopValue(line)
212		if lerr != nil {
213			return nil, lerr
214		}
215		if ok != '{' {
216			return nil, &LineError{Status: "error", Error: "invalid JSON: input must be a query object"}
217		}
218		return s.queryFromObject(top)
219	}
220	
221	// validateLineText 在 JSON 解析之前强制整行文本合法：原始字节必须是合法
222	// UTF-8，字符串内的 Unicode 转义必须表示有效字符。编码层/JSON 解析器会把
223	// 非法字节或未配对代理项静默替换成 U+FFFD，使损坏文本混入合法序列（被误判为
224	// 重复、冲突或错误命中查询），因此这里一律拒绝而不是修补后继续。
225	//
226	// 逐字节扫描、只在字符串内部识别转义：跳过词法空白与全部非字符串 token。
227	// 被转义的反斜杠（\\）后的 "uXXXX" 只是普通文本，不会被当成 Unicode 转义。
228	func validateLineText(line string) *LineError {
229		if !utf8.ValidString(line) {
230			return &LineError{Status: "error", Error: "invalid JSON: input is not valid UTF-8 text"}
231		}
232		inString := false
233		for i := 0; i < len(line); i++ {
234			c := line[i]
235			if !inString {
236				if c == '"' {
237					inString = true
238				}
239				continue
240			}
241			switch c {
242			case '"':
243				inString = false
244			case '\\':
245				if i+1 >= len(line) {
246					break // 悬空反斜杠：交给 JSON 解析器报错
247				}
248				if line[i+1] != 'u' {
249					i++ // 单字符转义（\\、\"、\n 等），跳过被转义字符
250					continue
251				}
252				// i 指向 '\'，i+1 指向 'u'；转义占据 i..i+5。
253				r, size := decodeJSONHexEscape(line, i+1)
254				if size == 0 {
255					return &LineError{Status: "error", Error: "invalid JSON: invalid Unicode escape sequence"}
256				}
257				if !utf16.IsSurrogate(r) {
258					i += 5
259					continue
260				}
261				if r >= 0xDC00 {
262					// 单独出现的低代理项。
263					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
264				}
265				// 高代理项后必须紧接另一个表示低代理项的 \uXXXX 转义。
266				loPos := i + 6 // 第一个转义之后的字符位置
267				if loPos+1 >= len(line) || line[loPos] != '\\' || line[loPos+1] != 'u' {
268					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
269				}
270				lo, loSize := decodeJSONHexEscape(line, loPos+1)
271				if loSize == 0 || lo < 0xDC00 || lo > 0xDFFF {
272					return &LineError{Status: "error", Error: "invalid JSON: unpaired Unicode surrogate escape"}
273				}
274				i = loPos + loSize // 跳到第二转义的最后一个十六进制位，循环自增后越出
275			}
276		}
277		return nil
278	}
279	
280	// decodeJSONHexEscape 解析 line[pos:] 处的 "uXXXX"（pos 指向 'u'），
281	// 返回其码元与占用字节数（固定为 5）；不足四个十六进制数字时 size 为 0。
282	func decodeJSONHexEscape(line string, pos int) (rune, int) {
283		if pos+4 >= len(line) {
284			return 0, 0
285		}
286		var v rune
287		for j := pos + 1; j <= pos+4; j++ {
288			c := line[j]
289			var d rune
290			switch {
291			case c >= '0' && c <= '9':
292				d = rune(c - '0')
293			case c >= 'a' && c <= 'f':
294				d = rune(c-'a') + 10
295			case c >= 'A' && c <= 'F':
296				d = rune(c-'A') + 10
297			default:
298				return 0, 0
299			}
300			v = v<<4 | d
301		}
302		return v, 5
303	}
304	
305	// decodeTopValue 解析单行中唯一的 JSON 值并返回其原始内容与首个非空白字节
306	// （'[' 或 '{'）。整个值无法解析、为空或存在尾随内容时返回 *LineError。
307	func decodeTopValue(line string) (json.RawMessage, byte, *LineError) {
308		if lerr := validateLineText(line); lerr != nil {
309			return nil, 0, lerr
310		}
311		dec := json.NewDecoder(strings.NewReader(line))
312		var top json.RawMessage
313		if err := dec.Decode(&top); err != nil {
314			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
315		}
316		// 第一个 JSON 值之后只允许输入结束（Decoder 自动跳过尾随空白）。
317		if err := dec.Decode(new(json.RawMessage)); err != io.EOF {
318			if err == nil {
319				err = fmt.Errorf("unexpected content after the JSON value")
320			}
321			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: " + err.Error()}
322		}
323		trimmed := strings.TrimSpace(string(top))
324		if len(trimmed) == 0 || (trimmed[0] != '[' && trimmed[0] != '{') {
325			return nil, 0, &LineError{Status: "error", Error: "invalid JSON: input must be a JSON array of samples or a query object"}
326		}
327		return top, trimmed[0], nil
328	}
329	
330	type parsedSample struct {
331		name   string
332		ts     int64
333		value  float64
334		labels map[string]string
335	}
336	
337	// parseSample 对单个采样点做严格校验：仅允许四个已知字段、拒绝重复键，
338	// 标量必须是精确的 JSON 类型，timestamp 为 int64 整数，value 为有限 float64。
339	func parseSample(raw json.RawMessage) (parsedSample, error) {
340		var p parsedSample
341		p.labels = map[string]string{}
342		dec := json.NewDecoder(bytes.NewReader(raw))
343		dec.UseNumber()
344	
345		tok, err := dec.Token()
346		if err != nil {
347			return p, err
348		}
349		if d, ok := tok.(json.Delim); !ok || d != '{' {
350			return p, fmt.Errorf("each sample must be a JSON object")
351		}
352	
353		present := make(map[string]bool)
354		for dec.More() {
355			keyTok, err := dec.Token()
356			if err != nil {
357				return p, err
358			}
359			key := keyTok.(string)
360			switch key {
361			case "name", "timestamp", "value", "labels":
362			default:
363				return p, fmt.Errorf("unknown field %q", key)
364			}
365			if present[key] {
366				return p, fmt.Errorf("duplicate field %q", key)
367			}
368			present[key] = true
369	
370			switch key {
371			case "name":
372				t, err := dec.Token()
373				if err != nil {
374					return p, err
375				}
376				s, ok := t.(string)
377				if !ok {
378					return p, fmt.Errorf(`field "name" must be a string`)
379				}
380				if s == "" {
381					return p, fmt.Errorf(`field "name" must be a non-empty string`)
382				}
383				p.name = s
384			case "timestamp":
385				n, err := nextJSONNumber(dec, "timestamp")
386				if err != nil {
387					return p, err
388				}
389				v, err := parseJSONInt(n)
390				if err != nil {
391					return p, fmt.Errorf(`field "timestamp": %s`, err)
392				}
393				p.ts = v
394			case "value":
395				n, err := nextJSONNumber(dec, "value")
396				if err != nil {
397					return p, err
398				}
399				v, err := parseFiniteFloat(n)
400				if err != nil {
401					return p, fmt.Errorf(`field "value": %s`, err)
402				}
403				p.value = v
404			case "labels":
405				labels, err := parseLabels(dec, `field "labels" must be an object of string keys to string values`)
406				if err != nil {
407					return p, err
408				}
409				p.labels = labels
410			}
411		}
412		if _, err := dec.Token(); err != nil { // 消耗 '}'
413			return p, err
414		}
415		if _, err := dec.Token(); err != io.EOF {
416			if err == nil {
417				return p, fmt.Errorf("unexpected content after the sample object")
418			}
419			return p, err
420		}
421	
422		for _, field := range []string{"name", "timestamp", "value"} {
423			if !present[field] {
424				return p, fmt.Errorf("missing required field %q", field)
425			}
426		}
427		return p, nil
428	}
429	
430	// parseLabels 从 dec 读取一个标签对象并做统一校验：必须是 JSON 对象
431	// （否则返回调用方给出的 notObjectMsg，写入与查询措辞不同），键为非空字符串、
432	// 值为字符串（空串合法，键值均不做清理），重复键一律拒绝。
433	// 返回的集合不含标签时也是非 nil 的空 map，与省略 labels 的语义一致。
434	func parseLabels(dec *json.Decoder, notObjectMsg string) (map[string]string, error) {
435		t, err := dec.Token()
436		if err != nil {
437			return nil, err
438		}
439		d, ok := t.(json.Delim)
440		if !ok || d != '{' {
441			return nil, fmt.Errorf("%s", notObjectMsg)
442		}
443		labels := map[string]string{}
444		for dec.More() {
445			labelKeyTok, err := dec.Token()
446			if err != nil {
447				return nil, err
448			}
449			labelKey := labelKeyTok.(string)
450			if labelKey == "" {
451				return nil, fmt.Errorf(`field "labels": label keys must be non-empty strings`)
452			}
453			valTok, err := dec.Token()
454			if err != nil {
455				return nil, err
456			}
457			labelVal, ok := valTok.(string)
458			if !ok {
459				return nil, fmt.Errorf(`field "labels": value of label %q must be a string`, labelKey)
460			}
461			if _, dup := labels[labelKey]; dup {
462				return nil, fmt.Errorf(`field "labels": duplicate label key %q`, labelKey)
463			}
464			labels[labelKey] = labelVal
465		}
466		if _, err := dec.Token(); err != nil { // 消耗 '}'
467			return nil, err
468		}
469		return labels, nil
470	}
471	
472	func nextJSONNumber(dec *json.Decoder, field string) (json.Number, error) {
473		t, err := dec.Token()
474		if err != nil {
475			return "", err
476		}
477		n, ok := t.(json.Number)
478		if !ok {
479			return "", fmt.Errorf(`field %q must be a JSON number`, field)
480		}
481		return n, nil
482	}
483	
484	func parseJSONInt(n json.Number) (int64, error) {
485		s := string(n)
486		if !jsonIntegerRE.MatchString(s) {
487			return 0, fmt.Errorf("must be a JSON integer in milliseconds")
488		}
489		v, err := strconv.ParseInt(s, 10, 64)
490		if err != nil {
491			return 0, fmt.Errorf("must be within int64 range")
492		}
493		return v, nil
494	}
495	
496	func parseFiniteFloat(n json.Number) (float64, error) {
497		s := string(n)
498		if !jsonNumberRE.MatchString(s) {
499			return 0, fmt.Errorf("must be a JSON number")
500		}
501		v, err := strconv.ParseFloat(s, 64)
502		if err != nil || math.IsInf(v, 0) || math.IsNaN(v) {
503			return 0, fmt.Errorf("must be a finite number representable as float64")
504		}
505		return v, nil
506	}
507	
508	// ingestItems 完成全部采样点校验与冲突检测后再统一提交，保证整批原子性。
509	func (s *MetricStore) ingestItems(items []json.RawMessage) (*BatchResult, *LineError) {
510		type pending struct {
511			id  seriesID
512			ref SeriesRef
513			ts  int64
514			val float64
515		}
516	
517		added := 0
518		// 本批已确定身份的点（含与已写入数据重复的点），用于批内去重与冲突检测。
519		seen := make(map[seriesID]map[int64]float64)
520		// 仅记录需要落盘的新增点；校验全部通过后才提交。
521		commits := make([]pending, 0, len(items))
522	
523		failAt := func(index int, msg string) *LineError {
524			return &LineError{Status: "error", Index: index, Error: msg}
525		}
526		conflictAt := func(index int, ref SeriesRef, ts int64, existing, submitted float64) *LineError {
527			return &LineError{
528				Status: "error",
529				Index:  index,
530				Error: fmt.Sprintf("conflict: series %s at timestamp %d already has value %s, submitted %s",
531					ref, ts, formatFloat(existing), formatFloat(submitted)),
532				Conflict: &Conflict{
533					// 标签必须复制：冲突结果是本次失败的独立记录，
534					// 调用方修改它不能改动已存序列的身份。
535					Series:    SeriesRef{Name: ref.Name, Labels: cloneLabels(ref.Labels)},
536					Timestamp: ts,
537					Existing:  existing,
538					Submitted: submitted,
539				},
540			}
541		}
542	
543		for i, item := range items {
544			pos := i + 1
545			p, err := parseSample(item)
546			if err != nil {
547				return nil, failAt(pos, err.Error())
548			}
549	
550			id := makeSeriesID(p.name, p.labels)
551			ref := SeriesRef{Name: p.name, Labels: p.labels}
552	
553			if byTS, ok := seen[id]; ok {
554				if old, ok := byTS[p.ts]; ok {
555					if old != p.value {
556						return nil, conflictAt(pos, ref, p.ts, old, p.value)
557					}
558					// 同批内重复出现且数值相同：重复，成功忽略。
559					continue
560				}
561			}
562			if sr, ok := s.series[id]; ok {
563				if old, ok := sr.points[p.ts]; ok {
564					if old != p.value {
565						return nil, conflictAt(pos, sr.ref, p.ts, old, p.value)
566					}
567					// 与此前批次已写入的值相同：重复，成功忽略。
568					if seen[id] == nil {
569						seen[id] = map[int64]float64{}
570					}
571					seen[id][p.ts] = p.value
572					continue
573				}
574			}
575	
576			added++
577			if seen[id] == nil {
578				seen[id] = map[int64]float64{}
579			}
580			seen[id][p.ts] = p.value
581			commits = append(commits, pending{id: id, ref: ref, ts: p.ts, val: p.value})
582		}
583	
584		// 全部采样点合法且无冲突，原子提交本批新增点。
585		for _, c := range commits {
586			sr := s.series[c.id]
587			if sr == nil {
588				sr = &storedSeries{ref: c.ref, points: map[int64]float64{}}
589				s.series[c.id] = sr
590			}
591			sr.points[c.ts] = c.val
592		}
593	
594		return s.snapshot(added, len(items)-added), nil
595	}
596	
597	// formatFloat 以 JSON 数值风格格式化 float64：1 与 1.0 均显示为 1。
598	func formatFloat(v float64) string {
599		return strconv.FormatFloat(v, 'g', -1, 64)
600	}
601	
602	type parsedQuery struct {
603		name   string
604		start  int64
605		end    int64
606		labels map[string]string
607	}
608	
609	// queryFromObject 严格解析查询对象并执行只读区间均值查询。
610	func (s *MetricStore) queryFromObject(raw json.RawMessage) (*QueryResult, *LineError) {
611		q, err := parseQuery(raw)
612		if err != nil {
613			return nil, &LineError{Status: "error", Error: err.Error()}
614		}
615		if q.start > q.end {
616			return nil, &LineError{Status: "error", Error: fmt.Sprintf(
617				`invalid range: "start" must not be greater than "end" (%d > %d)`, q.start, q.end)}
618		}
619		return s.runQuery(q), nil
620	}
621	
622	// parseQuery 对查询对象做严格校验：仅允许 op/name/start/end/labels，
623	// 拒绝重复键与未知字段；标量必须是精确的 JSON 类型，start/end 为 int64 毫秒。
624	func parseQuery(raw json.RawMessage) (parsedQuery, error) {
625		var q parsedQuery
626		dec := json.NewDecoder(bytes.NewReader(raw))
627		dec.UseNumber()
628	
629		tok, err := dec.Token()
630		if err != nil {
631			return q, err
632		}
633		if d, ok := tok.(json.Delim); !ok || d != '{' {
634			return q, fmt.Errorf("each query must be a JSON object")
635		}
636	
637		present := make(map[string]bool)
638		for dec.More() {
639			keyTok, err := dec.Token()
640			if err != nil {
641				return q, err
642			}
643			key := keyTok.(string)
644			switch key {
645			case "op", "name", "start", "end", "labels":
646			default:
647				return q, fmt.Errorf("unknown field %q", key)
648			}
649			if present[key] {
650				return q, fmt.Errorf("duplicate field %q", key)
651			}
652			present[key] = true
653	
654			switch key {
655			case "op":
656				t, err := dec.Token()
657				if err != nil {
658					return q, err
659				}
660				op, ok := t.(string)
661				if !ok {
662					return q, fmt.Errorf(`field "op" must be a string`)
663				}
664				if op != "query" {
665					return q, fmt.Errorf(`unknown op %q (only "query" is supported)`, op)
666				}
667			case "name":
668				t, err := dec.Token()
669				if err != nil {
670					return q, err
671				}
672				name, ok := t.(string)
673				if !ok {
674					return q, fmt.Errorf(`field "name" must be a string`)
675				}
676				if name == "" {
677					return q, fmt.Errorf(`field "name" must be a non-empty string`)
678				}
679				q.name = name
680			case "start", "end":
681				n, err := nextJSONNumber(dec, key)
682				if err != nil {
683					return q, err
684				}
685				v, err := parseJSONInt(n)
686				if err != nil {
687					return q, fmt.Errorf(`field %q: %s`, key, err)
688				}
689				if key == "start" {
690					q.start = v
691				} else {
692					q.end = v
693				}
694			case "labels":
695				labels, err := parseLabels(dec, `field "labels" must be an object of non-empty string keys to string values`)
696				if err != nil {
697					return q, err
698				}
699				q.labels = labels
700			}
701		}
702		if _, err := dec.Token(); err != nil { // 消耗 '}'
703			return q, err
704		}
705		if _, err := dec.Token(); err != io.EOF {
706			if err == nil {
707				return q, fmt.Errorf("unexpected content after the query object")
708			}
709			return q, err
710		}
711	
712		for _, field := range []string{"op", "name", "start", "end"} {
713			if !present[field] {
714				return q, fmt.Errorf("missing required field %q", field)
715			}
716		}
717		return q, nil
718	}
719	
720	// labelsMatch 实现子集匹配：want 中每个键都必须在 stored 中存在且值完全相等，
721	// stored 可以含额外标签；空字符串值只匹配真实存在的空值标签。
722	func labelsMatch(want, stored map[string]string) bool {
723		for k, v := range want {
724			got, ok := stored[k]
725			if !ok || got != v {
726				return false
727			}
728		}
729		return true
730	}
731	
732	// runQuery 只读扫描已成功提交的数据：name 精确、标签子集、[start,end] 闭区间。
733	// 结果沿用 snapshot 的序列排序；无区间内点的序列不列出。
734	func (s *MetricStore) runQuery(q parsedQuery) *QueryResult {
735		matched := make([]*storedSeries, 0)
736		for _, sr := range s.series {
737			if sr.ref.Name != q.name || !labelsMatch(q.labels, sr.ref.Labels) {
738				continue
739			}
740			has := false
741			for ts := range sr.points {
742				if ts >= q.start && ts <= q.end {
743					has = true
744					break
745				}
746			}
747			if has {
748				matched = append(matched, sr)
749			}
750		}
751		sort.Slice(matched, func(i, j int) bool {
752			if matched[i].ref.Name != matched[j].ref.Name {
753				return matched[i].ref.Name < matched[j].ref.Name
754			}
755			return compareLabelPairs(sortedPairs(matched[i].ref.Labels), sortedPairs(matched[j].ref.Labels)) < 0
756		})
757	
758		out := make([]QuerySeries, 0, len(matched))
759		for _, sr := range matched {
760			tsList := make([]int64, 0, len(sr.points))
761			for ts := range sr.points {
762				if ts >= q.start && ts <= q.end {
763					tsList = append(tsList, ts)
764				}
765			}
766			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
767			values := make([]float64, len(tsList))
768			for i, ts := range tsList {
769				values[i] = sr.points[ts]
770			}
771			labels := cloneLabels(sr.ref.Labels)
772			out = append(out, QuerySeries{
773				Name:    sr.ref.Name,
774				Labels:  labels,
775				Count:   len(values),
776				Average: finiteMean(values),
777			})
778		}
779		return &QueryResult{Status: "ok", Op: "query", Series: out}
780	}
781	
782	// finiteMean 返回已存储 float64 值的精确算术平均所对应的最近 float64，
783	// 恰好在两个相邻可表示值中间时按最近偶数舍入。
784	// 求和用有理数精确完成：与点的顺序、批次划分无关，正负大数抵消后的小余量
785	// 不会丢失，总和超出 float64 范围时结果仍然有限。精确平均为零时返回 +0；
786	// 只有一个点时结果就是该点的值。
787	func finiteMean(values []float64) float64 {
788		sum := new(big.Rat)
789		r := new(big.Rat)
790		for _, v := range values {
791			// 写入侧已保证 v 有限，SetFloat64 对有限值是精确的。
792			sum.Add(sum, r.SetFloat64(v))
793		}
794		sum.Quo(sum, r.SetInt64(int64(len(values))))
795		return ratToFloat64NearestEven(sum)
796	}
797	
798	// ratToFloat64NearestEven 把有理数 x 舍入到最近的 float64，半数取偶。
799	// 调用方保证 |x| 不超过 MaxFloat64（有限值的均值必然满足），因此不会溢出。
800	func ratToFloat64NearestEven(x *big.Rat) float64 {
801		if x.Sign() == 0 {
802			return 0
803		}
804		num := new(big.Int).Set(x.Num())
805		den := x.Denom()
806		neg := num.Sign() < 0
807		if neg {
808			num.Neg(num)
809		}
810	
811		// e 满足 2^e <= num/den < 2^(e+1)。
812		e := floorLog2Rat(num, den)
813		var m *big.Int
814		scale := 0
815		if e >= -1022 {
816			// 正规数：m 为 num/den 按 2^(e-52) 缩放后的 53 位舍入整数。
817			scale = e - 52
818			m = roundScaledRatio(num, den, scale)
819			if m.BitLen() == 54 {
820				// 舍入进位（如 1.111…1 进为 10.0），指数加一。
821				m.Rsh(m, 1)
822				scale++
823			}
824		} else {
825			// 次正规数：有效位间距固定为 2^-1074；m 舍入为 0 时按 IEEE 得到带符号零。
826			scale = -1074
827			m = roundScaledRatio(num, den, scale)
828		}
829		// m < 2^53，可以精确放入 int64 与 float64。
830		f := math.Ldexp(float64(m.Int64()), scale)
831		if neg {
832			return -f
833		}
834		return f
835	}
836	
837	// floorLog2Rat 返回正有理数 num/den 的二进制阶：最大的 e 使 2^e <= num/den。
838	func floorLog2Rat(num, den *big.Int) int {
839		k := num.BitLen() - den.BitLen()
840		var t big.Int
841		if k >= 0 {
842			t.Lsh(den, uint(k))
843			if num.Cmp(&t) >= 0 {
844				return k
845			}
846			return k - 1
847		}
848		t.Lsh(num, uint(-k))
849		if t.Cmp(den) >= 0 {
850			return k
851		}
852		return k - 1
853	}
854	
855	// roundScaledRatio 返回 round(num / (den · 2^scale))，半数取偶；num、den 均为正。
856	func roundScaledRatio(num, den *big.Int, scale int) *big.Int {
857		n := new(big.Int).Set(num)
858		d := new(big.Int).Set(den)
859		if scale >= 0 {
860			d.Lsh(d, uint(scale))
861		} else {
862			n.Lsh(n, uint(-scale))
863		}
864		q, r := new(big.Int).QuoRem(n, d, new(big.Int))
865		switch r2 := new(big.Int).Lsh(r, 1); r2.Cmp(d) {
866		case 1:
867			q.Add(q, big.NewInt(1))
868		case 0:
869			if q.Bit(0) == 1 {
870				q.Add(q, big.NewInt(1))
871			}
872		}
873		return q
874	}
875	
876	// String 让冲突原因中的序列身份可读：name{k=v,...}，标签按键排序。
877	func (r SeriesRef) String() string {
878		var b strings.Builder
879		b.WriteString(r.Name)
880		b.WriteByte('{')
881		for i, p := range sortedPairs(r.Labels) {
882			if i > 0 {
883				b.WriteByte(',')
884			}
885			fmt.Fprintf(&b, "%s=%s", p.Key, p.Value)
886		}
887		b.WriteByte('}')
888		return b.String()
889	}
890	
891	// snapshot 生成按规范排序的全部序列视图：先按指标名，再按标签键值对字典序，
892	// 序列内按时间戳升序。
893	func (s *MetricStore) snapshot(added, duplicates int) *BatchResult {
894		views := make([]SeriesView, 0, len(s.series))
895		for _, sr := range s.series {
896			tsList := make([]int64, 0, len(sr.points))
897			for ts := range sr.points {
898				tsList = append(tsList, ts)
899			}
900			sort.Slice(tsList, func(i, j int) bool { return tsList[i] < tsList[j] })
901			points := make([]Point, len(tsList))
902			for i, ts := range tsList {
903				points[i] = Point{Timestamp: ts, Value: sr.points[ts]}
904			}
905			views = append(views, SeriesView{Name: sr.ref.Name, Labels: cloneLabels(sr.ref.Labels), Points: points})
906		}
907		sort.Slice(views, func(i, j int) bool {
908			if views[i].Name != views[j].Name {
909				return views[i].Name < views[j].Name
910			}
911			return compareLabelPairs(sortedPairs(views[i].Labels), sortedPairs(views[j].Labels)) < 0
912		})
913		return &BatchResult{Status: "ok", Added: added, Duplicates: duplicates, Series: views}
914	}
915

