2	
3	import (
4		"reflect"
5		"testing"
6	)
7	
8	// 本文件回归保障成功结果的隔离性：写入批次返回的序列快照（BatchResult.Series）
9	// 与区间查询返回的结果（QueryResult.Series）都是当次操作的独立结果。
10	// 调用方整理指标名、标签、点、count/average 或结果条目顺序，都不得改动已写入的
11	// 序列身份与点的事实，也不得影响此前/此后取得的其他成功结果。
12	// 与 alias_repro_test.go 中的冲突结果隔离测试相对应。
13	
14	// findViewIndex 在写入快照中找到指定指标名与完整标签集合的序列下标。
15	func findViewIndex(t *testing.T, res *BatchResult, name string, labels map[string]string) int {
16		t.Helper()
17		for i, v := range res.Series {
18			if v.Name == name && reflect.DeepEqual(v.Labels, labels) {
19				return i
20			}
21		}
22		t.Fatalf("series %s %v not found in snapshot: %+v", name, labels, res.Series)
23		return -1
24	}
25	
26	// findQueryIndex 在查询结果中找到指定指标名与完整标签集合的条目下标。
27	func findQueryIndex(t *testing.T, res *QueryResult, name string, labels map[string]string) int {
28		t.Helper()
29		for i, v := range res.Series {
30			if v.Name == name && reflect.DeepEqual(v.Labels, labels) {
31				return i
32			}
33		}
34		t.Fatalf("series %s %v not found in query result: %+v", name, labels, res.Series)
35		return -1
36	}
37	
38	// 写入快照是独立结果：改指标名、标签、点的时间戳/数值或追加点，
39	// 都不能改变存储中的序列身份与点的事实。
40	func TestSnapshotMutationDoesNotChangeStoredIdentity(t *testing.T) {
41		s := NewMetricStore()
42		// 同一存储中安排四条 cpu 序列：host=a 两个点（count=2、average=3），
43		// 一条同名不同标签序列，一条无标签序列，一条空字符串标签值序列。
44		snap := mustOK(t, s, `[
45			{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
46			{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
47			{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}},
48			{"name":"cpu","timestamp":1000,"value":6},
49			{"name":"cpu","timestamp":1000,"value":7,"labels":{"zone":""}}
50		]`)
51		if snap.Added != 5 || snap.Duplicates != 0 || len(snap.Series) != 4 {
52			t.Fatalf("initial batch = %+v, want added=5 and 4 series", snap)
53		}
54	
55		// 事实基线：完整区间查询 host=a 返回 count=2、average=3。
56		qr := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
57		if len(qr.Series) != 1 || qr.Series[0].Count != 2 || qr.Series[0].Average != 3 {
58			t.Fatalf("baseline host=a query = %+v, want count=2 average=3", qr.Series)
59		}
60	
61		// 调用方取得快照后整理 host=a 视图：改名、换标签、加标签、
62		// 改两个点的时间戳与数值、追加一个伪造点。
63		a := &snap.Series[findViewIndex(t, snap, "cpu", map[string]string{"host": "a"})]
64		a.Name = "cpu-renamed"
65		a.Labels["host"] = "c"
66		a.Labels["zone"] = "z"
67		a.Points[0].Timestamp = 99999
68		a.Points[0].Value = 99
69		a.Points[1].Timestamp = 88888
70		a.Points[1].Value = 88
71		a.Points = append(a.Points, Point{Timestamp: 1, Value: 1})
72	
73		// 同名不同标签的同伴视图也被调用方整理。
74		b := &snap.Series[findViewIndex(t, snap, "cpu", map[string]string{"host": "b"})]
75		b.Labels["host"] = "d"
76		b.Points[0].Value = 55
77	
78		// 原名称 + 原标签查到的仍是原事实：1000->2、2000->4。
79		qr = mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
80		if len(qr.Series) != 1 {
81			t.Fatalf("host=a query = %+v, want one series", qr.Series)
82		}
83		got := qr.Series[0]
84		if got.Name != "cpu" || len(got.Labels) != 1 || got.Labels["host"] != "a" ||
85			got.Count != 2 || got.Average != 3 {
86			t.Fatalf("host=a fact changed after snapshot mutation: %+v", got)
87		}
88	
89		// 同伴序列不受 host=a 视图修改影响。
90		qr = mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"b"}}`)
91		if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 5 {
92			t.Fatalf("host=b fact changed: %+v, want count=1 average=5", qr.Series)
93		}
94	
95		// 按快照里改出的身份查询，不能凭空找到新序列。
96		for _, line := range []string{
97			`{"op":"query","name":"cpu","start":0,"end":100000,"labels":{"host":"c"}}`,
98			`{"op":"query","name":"cpu","start":0,"end":100000,"labels":{"host":"d"}}`,
99			`{"op":"query","name":"cpu","start":0,"end":100000,"labels":{"host":"a","zone":"z"}}`,
100			`{"op":"query","name":"cpu-renamed","start":0,"end":100000,"labels":{"host":"c"}}`,
101		} {
102			qr = mustQuery(t, s, line)
103			if len(qr.Series) != 0 {
104				t.Fatalf("mutated identity %s must not match, got %+v", line, qr.Series)
105			}
106		}
107		// 快照里改出的时间戳在存储中不存在。
108		qr = mustQuery(t, s, `{"op":"query","name":"cpu","start":80000,"end":100000,"labels":{"host":"a"}}`)
109		if len(qr.Series) != 0 {
110			t.Fatalf("mutated timestamps must not be stored, got %+v", qr.Series)
111		}
112	
113		// 再次提交原时间戳、原数值仍是重复（存储认的是真实值 2，不是快照里改出的 99）。
114		dup := mustOK(t, s, `[{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}}]`)
115		if dup.Added != 0 || dup.Duplicates != 1 || len(dup.Series) != 4 {
116			t.Fatalf("resubmit original point = %+v, want one duplicate and still 4 series", dup)
117		}
118	
119		// 提交不同数值：冲突报告真实已存值 2，而不是调用方在快照里改出的 99；
120		// 冲突失败仍是整批不写入，改出的时间戳依旧没有点。
121		lerr := mustFail(t, s, `[{"name":"cpu","timestamp":1000,"value":99,"labels":{"host":"a"}}]`)
122		if lerr.Conflict == nil {
123			t.Fatalf("expected conflict, got %+v", lerr)
124		}
125		c := lerr.Conflict
126		if c.Series.Name != "cpu" || c.Series.Labels["host"] != "a" || len(c.Series.Labels) != 1 ||
127			c.Timestamp != 1000 || c.Existing != 2 || c.Submitted != 99 {
128			t.Fatalf("conflict must report stored fact, got %+v", c)
129		}
130		// 同伴序列同理：快照里改成 55，但真实已存值仍是 5。
131		lerr = mustFail(t, s, `[{"name":"cpu","timestamp":1000,"value":55,"labels":{"host":"b"}}]`)
132		if lerr.Conflict == nil || lerr.Conflict.Existing != 5 || lerr.Conflict.Submitted != 55 {
133			t.Fatalf("host=b conflict must report existing=5, got %+v", lerr.Conflict)
134		}
135	
136		// 之后取得的新快照是新的独立结果，仍按存储事实呈现。
137		snap2 := mustOK(t, s, `[]`)
138		if len(snap2.Series) != 4 {
139			t.Fatalf("fresh snapshot = %+v, want 4 series", snap2.Series)
140		}
141		a2 := snap2.Series[findViewIndex(t, snap2, "cpu", map[string]string{"host": "a"})]
142		if a2.Name != "cpu" || len(a2.Labels) != 1 || a2.Labels["host"] != "a" || len(a2.Points) != 2 {
143			t.Fatalf("fresh host=a view = %+v", a2)
144		}
145		if a2.Points[0] != (Point{Timestamp: 1000, Value: 2}) ||
146			a2.Points[1] != (Point{Timestamp: 2000, Value: 4}) {
147			t.Fatalf("fresh host=a points = %+v, want (1000,2),(2000,4)", a2.Points)
148		}
149		bv := snap2.Series[findViewIndex(t, snap2, "cpu", map[string]string{"host": "b"})]
150		if bv.Labels["host"] != "b" || bv.Points[0].Value != 5 {
151			t.Fatalf("fresh host=b view = %+v, want host=b value 5", bv)
152		}
153	}
154	
155	// 无标签序列与空字符串标签值序列：向返回的空标签集合加键、删除返回的空值标签、
156	// 修改返回点的时间戳或数值，都不能改变存储中的身份区别。
157	func TestSnapshotEmptyAndEmptyValueLabelsIndependent(t *testing.T) {
158		s := NewMetricStore()
159		snap := mustOK(t, s, `[
160			{"name":"cpu","timestamp":1000,"value":6},
161			{"name":"cpu","timestamp":1000,"value":7,"labels":{"zone":""}},
162			{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}}
163		]`)
164	
165		none := &snap.Series[findViewIndex(t, snap, "cpu", map[string]string{})]
166		if none.Labels == nil {
167			t.Fatal("snapshot labels for unlabeled series must be non-nil empty map")
168		}
169		emptyVal := &snap.Series[findViewIndex(t, snap, "cpu", map[string]string{"zone": ""})]
170	
171		// 调用方整理两个返回视图：空集合加键、空值标签删键、改点值与时间戳。
172		none.Labels["host"] = "x"
173		none.Points[0].Value = 66
174		delete(emptyVal.Labels, "zone")
175		emptyVal.Points[0].Timestamp = 5000
176	
177		// 无标签身份仍是无标签：全量结果中仍有一条标签为空、值为 6 的序列。
178		qr := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
179		if len(qr.Series) != 3 {
180			t.Fatalf("full cpu query = %+v, want 3 distinct series", qr.Series)
181		}
182		unlabeled := qr.Series[findQueryIndex(t, qr, "cpu", map[string]string{})]
183		if unlabeled.Count != 1 || unlabeled.Average != 6 {
184			t.Fatalf("unlabeled series fact changed: %+v", unlabeled)
185		}
186		// 空字符串标签值身份仍保留该键，点的时间戳仍是 1000。
187		zoneEmpty := qr.Series[findQueryIndex(t, qr, "cpu", map[string]string{"zone": ""})]
188		if zoneEmpty.Count != 1 || zoneEmpty.Average != 7 {
189			t.Fatalf("empty-value series fact changed: %+v", zoneEmpty)
190		}
191	
192		// 按原有标签规则筛选：加出来的 host=x 不匹配任何序列；
193		// 空值标签查询仍只命中真实存在的空值序列。
194		if qr = mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"x"}}`); len(qr.Series) != 0 {
195			t.Fatalf("added label must not match: %+v", qr.Series)
196		}
197		if qr = mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"zone":""}}`); len(qr.Series) != 1 {
198			t.Fatalf("empty-value label must still match its series: %+v", qr.Series)
199		}
200		// 快照里改出的时间戳不存在；原时间戳仍可查到。
201		if qr = mustQuery(t, s, `{"op":"query","name":"cpu","start":4000,"end":6000,"labels":{"zone":""}}`); len(qr.Series) != 0 {
202			t.Fatalf("mutated timestamp must not be stored: %+v", qr.Series)
203		}
204		// 提交被改出的数值 66 冲突于真实值 6。
205		lerr := mustFail(t, s, `[{"name":"cpu","timestamp":1000,"value":66}]`)
206		if lerr.Conflict == nil || lerr.Conflict.Existing != 6 || len(lerr.Conflict.Series.Labels) != 0 {
207			t.Fatalf("unlabeled conflict must report existing=6 with empty labels, got %+v", lerr.Conflict)
208		}
209	}
210	
211	// assertFullCPUResult 校验完整 cpu 查询恰好为四条身份与事实明确的序列，
212	// 顺序与 snapshot 排序一致：无标签、host=a、host=b、zone=""。
213	func assertFullCPUResult(t *testing.T, qr *QueryResult) {
214		t.Helper()
215		if qr.Status != "ok" || qr.Op != "query" {
216			t.Fatalf("result envelope = %+v, want ok query", qr)
217		}
218		want := []struct {
219			labels  map[string]string
220			count   int
221			average float64
222		}{
223			{map[string]string{}, 1, 6},
224			{map[string]string{"host": "a"}, 2, 3},
225			{map[string]string{"host": "b"}, 1, 5},
226			{map[string]string{"zone": ""}, 1, 7},
227		}
228		if len(qr.Series) != len(want) {
229			t.Fatalf("series = %+v, want %d entries", qr.Series, len(want))
230		}
231		for i, w := range want {
232			got := qr.Series[i]
233			if got.Name != "cpu" || !reflect.DeepEqual(got.Labels, w.labels) ||
234				got.Count != w.count || got.Average != w.average {
235				t.Fatalf("series[%d] = %+v, want labels %v count %d average %v",
236					i, got, w.labels, w.count, w.average)
237			}
238		}
239	}
240	
241	// 查询结果是独立结果：改返回条目的标签、count、average 或整理结果条目，
242	// 不污染另一份已取得的查询结果，也不影响存储与之后的写入快照。
243	func TestQueryResultMutationDoesNotChangeStorage(t *testing.T) {
244		s := NewMetricStore()
245		mustOK(t, s, `[
246			{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
247			{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
248			{"name":"cpu","timestamp":1000,"value":5,"labels":{"host":"b"}},
249			{"name":"cpu","timestamp":1000,"value":6},
250			{"name":"cpu","timestamp":1000,"value":7,"labels":{"zone":""}}
251		]`)
252	
253		// 先保留一份成功结果，随后修改另一份。
254		q0 := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
255		assertFullCPUResult(t, q0)
256		q1 := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
257	
258		// 调用方整理 q1 的各条目：改名、改标签、删标签、加标签，篡改 count/average。
259		a := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{"host": "a"})]
260		a.Name = "cpu-renamed"
261		a.Labels["host"] = "c"
262		a.Labels["extra"] = "e"
263		a.Count = 99
264		a.Average = 123
265	
266		b := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{"host": "b"})]
267		delete(b.Labels, "host")
268		b.Labels["host"] = "d"
269		b.Count = 7
270		b.Average = 77
271	
272		none := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{})]
273		if none.Labels == nil {
274			t.Fatal("query labels for unlabeled series must be non-nil empty map")
275		}
276		none.Labels["host"] = "x"
277		none.Count = 41
278		none.Average = 42
279	
280		emptyVal := &q1.Series[findQueryIndex(t, q1, "cpu", map[string]string{"zone": ""})]
281		delete(emptyVal.Labels, "zone")
282		emptyVal.Count = 5
283		emptyVal.Average = 9
284	
285		// 整理结果中的序列条目：反转顺序、截断并追加伪造条目、篡改信封字段。
286		for i, j := 0, len(q1.Series)-1; i < j; i, j = i+1, j-1 {
287			q1.Series[i], q1.Series[j] = q1.Series[j], q1.Series[i]
288		}
289		q1.Series = append(q1.Series[:1], QuerySeries{Name: "ghost", Labels: map[string]string{}, Count: 1})
290		q1.Status = "mutated"
291		q1.Op = "mutated"
292	
293		// 另一份此前取得的查询结果不被污染。
294		assertFullCPUResult(t, q0)
295		// 之后取得的查询结果仍按存储事实返回。
296		q2 := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
297		assertFullCPUResult(t, q2)
298	
299		// 之后的写入快照同样不被污染。
300		snap := mustOK(t, s, `[]`)
301		if len(snap.Series) != 4 {
302			t.Fatalf("snapshot after query mutation = %+v, want 4 series", snap.Series)
303		}
304		for _, want := range []struct {
305			labels map[string]string
306			value  float64
307		}{
308			{map[string]string{}, 6},
309			{map[string]string{"host": "a"}, 2},
310			{map[string]string{"host": "b"}, 5},
311			{map[string]string{"zone": ""}, 7},
312		} {
313			v := snap.Series[findViewIndex(t, snap, "cpu", want.labels)]
314			if v.Points[0].Value != want.value {
315				t.Fatalf("snapshot point for %v = %+v, want value %v", want.labels, v.Points, want.value)
316			}
317		}
318	
319		// 按改出的身份筛选查不到序列；原标签规则保持不变。
320		for _, line := range []string{
321			`{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"c"}}`,
322			`{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"d"}}`,
323			`{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"x"}}`,
324			`{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"a","extra":"e"}}`,
325			`{"op":"query","name":"cpu-renamed","start":0,"end":10000}`,
326			`{"op":"query","name":"ghost","start":0,"end":10000}`,
327		} {
328			if qr := mustQuery(t, s, line); len(qr.Series) != 0 {
329				t.Fatalf("mutated identity %s must not match, got %+v", line, qr.Series)
330			}
331		}
332		// 删除返回条目的空值标签不改变存储身份：空值筛选仍命中该序列。
333		qr := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"zone":""}}`)
334		if len(qr.Series) != 1 || qr.Series[0].Count != 1 || qr.Series[0].Average != 7 {
335			t.Fatalf("empty-value label selection = %+v, want the zone='' series", qr.Series)
336		}
337	}
338	
339	// 保留一份未修改的成功结果，再向存储写入新时间戳：新查询与新快照包含新增点，
340	// 先前保留的快照与查询结果仍表示各自取得时的数据，不跟着新写入变化。
341	func TestRetainedSuccessResultsStayFixedAfterNewWrite(t *testing.T) {
342		s := NewMetricStore()
343		snapBefore := mustOK(t, s, `[
344			{"name":"cpu","timestamp":1000,"value":2,"labels":{"host":"a"}},
345			{"name":"cpu","timestamp":2000,"value":4,"labels":{"host":"a"}},
346			{"name":"cpu","timestamp":1000,"value":8,"labels":{"host":"b"}}
347		]`)
348		qBefore := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
349		qAllBefore := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000}`)
350		if qBefore.Series[0].Count != 2 || qBefore.Series[0].Average != 3 {
351			t.Fatalf("retained host=a query baseline = %+v, want count=2 average=3", qBefore.Series)
352		}
353		if len(qAllBefore.Series) != 2 {
354			t.Fatalf("retained full query baseline = %+v, want 2 series", qAllBefore.Series)
355		}
356	
357		// 向 host=a 写入新时间戳 3000->6：average 变为 (2+4+6)/3 = 4。
358		write := mustOK(t, s, `[{"name":"cpu","timestamp":3000,"value":6,"labels":{"host":"a"}}]`)
359		if write.Added != 1 || write.Duplicates != 0 {
360			t.Fatalf("new timestamp write = %+v, want added=1", write)
361		}
362	
363		qAfter := mustQuery(t, s, `{"op":"query","name":"cpu","start":0,"end":10000,"labels":{"host":"a"}}`)
364		if len(qAfter.Series) != 1 || qAfter.Series[0].Count != 3 || qAfter.Series[0].Average != 4 {
365			t.Fatalf("new query after write = %+v, want count=3 average=4", qAfter.Series)
366		}
367		snapAfter := mustOK(t, s, `[]`)
368		aAfter := snapAfter.Series[findViewIndex(t, snapAfter, "cpu", map[string]string{"host": "a"})]
369		if len(aAfter.Points) != 3 || aAfter.Points[2] != (Point{Timestamp: 3000, Value: 6}) {
370			t.Fatalf("new snapshot must include new point, got %+v", aAfter.Points)
371		}
372	
373		// 先前保留的写入快照不跟着变化。
374		aBefore := snapBefore.Series[findViewIndex(t, snapBefore, "cpu", map[string]string{"host": "a"})]
375		if len(snapBefore.Series) != 2 || len(aBefore.Points) != 2 ||
376			aBefore.Points[0] != (Point{Timestamp: 1000, Value: 2}) ||
377			aBefore.Points[1] != (Point{Timestamp: 2000, Value: 4}) {
378			t.Fatalf("retained snapshot changed after new write: %+v", snapBefore.Series)
379		}
380		bBefore := snapBefore.Series[findViewIndex(t, snapBefore, "cpu", map[string]string{"host": "b"})]
381		if len(bBefore.Points) != 1 || bBefore.Points[0] != (Point{Timestamp: 1000, Value: 8}) {
382			t.Fatalf("retained host=b snapshot changed: %+v", bBefore)
383		}
384	
385		// 先前保留的查询结果也不跟着变化。
386		if len(qBefore.Series) != 1 || qBefore.Series[0].Count != 2 || qBefore.Series[0].Average != 3 {
387			t.Fatalf("retained host=a query changed: %+v", qBefore.Series)
388		}
389		if len(qAllBefore.Series) != 2 {
390			t.Fatalf("retained full query gained the new point: %+v", qAllBefore.Series)
391		}
392		if qAllBefore.Series[0].Count != 2 || qAllBefore.Series[0].Average != 3 ||
393			qAllBefore.Series[1].Count != 1 || qAllBefore.Series[1].Average != 8 {
394			t.Fatalf("retained full query facts changed: %+v", qAllBefore.Series)
395		}
396	}
