3	import (
4		"bytes"
5		"io"
6		"strings"
7		"testing"
8	)
9	
10	// 含非法 UTF-8 字节的输入行（name 中夹一个 0xFF）。
11	var rawBadUTF8Write = []byte(`[{"name":"cpu` + "\xff" + `","timestamp":1000,"value":1}]`)
12	
13	// TestRunIngestCorruptTextIsWholeLineFailure 覆盖端到端语义：
14	// 损坏行只产出一条带原始行号、无 index/conflict 的 error；此前数据保留，
15	// 后续写入与查询照常；损坏查询不返回替换后的匹配；进程非零退出。
16	func TestRunIngestCorruptTextIsWholeLineFailure(t *testing.T) {
17		input := io.MultiReader(
18			// 行 1：先成功写入一个真实的 cpu 序列与一个显式 U+FFFD 序列。
19			strings.NewReader(`[{"name":"cpu","timestamp":1000,"value":0.5,"labels":{"host":"a"}}]`+"\n"),
20			strings.NewReader(`[{"name":"m�","timestamp":1,"value":7}]`+"\n"),
21			// 行 3：非法 UTF-8 字节的写入，整行失败。
22			bytes.NewReader(append(append([]byte(nil), rawBadUTF8Write...), '\n')),
23			// 行 4：孤立代理项转义的写入，整行失败，且不得与 U+FFFD 序列合并。
24			strings.NewReader(`[{"name":"m\uD800","timestamp":1,"value":9}]`+"\n"),
25			// 行 5：孤立代理项转义的查询，失败，不得经替换命中真实 U+FFFD 序列。
26			strings.NewReader(`{"op":"query","name":"m\uD800","start":0,"end":10}`+"\n"),
27			// 行 6：非法字节查询，失败。
28			bytes.NewReader([]byte(`{"op":"query","name":"cpu`+"\xff"+`","start":0,"end":10}`+"\n")),
29			// 行 7：合法查询此前数据，仍应正常得到行 1 的点。
30			strings.NewReader(`{"op":"query","name":"cpu","start":0,"end":3000,"labels":{"host":"a"}}`+"\n"),
31			// 行 8：合法补充平面写入，确认后续输入按序处理且行为不变。
32			strings.NewReader(`[{"name":"😀","timestamp":1,"value":1}]`+"\n"),
33		)
34	
35		var out bytes.Buffer
36		if code := runIngest(input, &out); code == 0 {
37			t.Fatalf("exit code = 0, want non-zero because corrupt lines failed")
38		}
39	
40		lines := strings.Split(strings.TrimRight(out.String(), "\n"), "\n")
41		if len(lines) != 8 {
42			t.Fatalf("got %d output lines, want 8 (3 writes ok, 4 errors, 1 query ok): %v", len(lines), lines)
43		}
44	
45		// 行 1、行 2 成功。
46		if m := decodeResultLine(t, lines[0]); m["status"] != "ok" {
47			t.Fatalf("line 1 = %v, want ok", m)
48		}
49		if m := decodeResultLine(t, lines[1]); m["status"] != "ok" {
50			t.Fatalf("line 2 = %v, want ok", m)
51		}
52	
53		// 错误行：行号 3-6 全部为整行错误，无 index、无 conflict，原因可区分两类。
54		wantErr := []struct {
55			line   int
56			substr string
57		}{
58			{3, "UTF-8"},
59			{4, "surrogate"},
60			{5, "surrogate"},
61			{6, "UTF-8"},
62		}
63		for i, w := range wantErr {
